"""PreToolUse hook: docs/backlog/(PATRI|PORTAL)-*.md are generated by scripts/backlog/export.py (F127).
Hand edits are blocked (exit 2). README.md and MAPA-legado.md stay editable."""
import json
import re
import sys

EXPORT_RE = re.compile(r"(^|/)docs/backlog/(PATRI|PORTAL)-[^/]*\.md$", re.IGNORECASE)


def main():
    try:
        data = json.load(sys.stdin)
    except Exception:
        return 0
    inp = data.get("tool_input") or {}
    path = inp.get("file_path") or inp.get("notebook_path") or ""
    if path and EXPORT_RE.search(path.replace(chr(92), "/")):
        print(f"BLOCKED: {path} is an export generated from the GitHub issue. Do not edit it by hand: "
              "change the issue and re-run scripts/backlog/export.py (F127, issue #152).", file=sys.stderr)
        return 2
    return 0


if __name__ == "__main__":
    sys.exit(main())
